"""Rotated-dictionary PLANT for the H2b pipeline: a synthetic 'certified' table generated by the seat's own
wkb_poly + map_and_monic(rotated=True) at a chosen rational dictionary point and M = PLANT_M (default 5).
Used only when the environment variable PLANT=1 is set (gen_eqs.py / check.py)."""
import os, sys; sys.dont_write_bytecode = True
from fractions import Fraction as F
import sympy as sp
from run_second2 import sX, sY, cX, cY, pi_rot, wkb_poly, map_and_monic
PV = {sX: sp.Integer(-120), sY: sp.Integer(-6), cX: sp.Integer(7), cY: sp.Rational(15, 4), pi_rot: sp.Integer(2)}
MP = F(os.environ.get('PLANT_M', '5'))
def load_cert(sol, k, tv):
    e, _ = wkb_poly(MP, k)
    return sp.expand(map_and_monic(e, k, True).subs(PV))
